arguments.file_text:
@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted mb-2">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <p class="card-text"><strong>Ingredients:</strong> @recipe.Ingredients</p>
                        <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe")</PageTitle>

@if (Recipe is null)
{
    <p class="text-danger">Recipe not found.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="text-muted">⭐ @Recipe.AverageRating.ToString("F1") (@Recipe.RatingCount ratings)</p>

    <div class="card mb-4">
        <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
        <div class="card-body">
            <ul class="mb-0">
                @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-header"><h5 class="mb-0">Steps</h5></div>
        <div class="card-body">
            @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p class="mb-2">@step</p>
            }
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-header"><h5 class="mb-0">Rate This Recipe</h5></div>
        <div class="card-body">
            <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit Your Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@_submission.Title</strong>" with the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <div class="mb-3">
            <label class="form-label" for="title">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="category">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_submission.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Asian">Asian</option>
                <option value="Mexican">Mexican</option>
                <option value="Desserts">Desserts</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label" for="ingredients">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="_submission.Ingredients" placeholder="List ingredients separated by commas" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="steps">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_submission.Steps" placeholder="Describe each step on a new line" />
        </div>

        <button type="submit" class="btn btn-success btn-lg" disabled="@(!IsFormValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission _submission = new();
    private bool _submitted;

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(_submission.Title) &&
        !string.IsNullOrWhiteSpace(_submission.Category) &&
        !string.IsNullOrWhiteSpace(_submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(_submission.Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;
        RecipeService.SubmitRecipe(_submission);
        _submitted = true;
    }
}

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="@star star(s)">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    @if (_hasRated)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.8rem;
        cursor: pointer;
        color: #ffc107;
        transition: transform 0.1s;
    }
    .star-rating .star:hover {
        transform: scale(1.2);
    }
    .star-rating .star.selected {
        color: #ffc107;
    }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _selectedRating;
    private bool _hasRated;

    private void Rate(int stars)
    {
        if (_hasRated) return;
        _selectedRating = stars;
        _hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

